 const views={trab:'TRABAJADORES',chq:'CHEQUES',pagos:'PAGOS',audit:'PAGOS',vac:'VACACIONES',actas:'ACTAS',nom:'NOM035',papeles:'PAPELES',anual:'ANUALES'};
 const routes={PLATINUM_RECIBOS_IA:'DOCUMENTOS',PLATINUM_PAGOS_SABADO:'PAGOS',PLATINUM_FLOWS:'CONTROL',PLATINUM_RRHH:'CONTROL',openDetail:'TRABAJADORES',openForm:'TRABAJADORES',openControlEmpresarial:'CONTROL',openProyeccion:'PROYECCION',openProyContratista:'PROYECCION',openMovimientos:'MOVIMIENTOS',openIncidencias:'INCIDENCIAS',openAsistencia:'ASISTENCIA',openCuadrillas:'CUADRILLAS',openImportPago:'PAGOS',openControlPagos:'PAGOS',openPdfImport:'DOCUMENTOS',openCfdiImport:'CFDI',openAvisosInfonavit:'CREDITOS',openCalendarioRet:'CREDITOS',openDashboard:'REPORTES',openPersonalHistorico:'REPORTES',openPlantillaFecha:'REPORTES',openContratistas:'ADMINISTRACION',openHistorial:'ADMINISTRACION',openBitacoraNomina:'ADMINISTRACION',openIA:'OTRO'};
 const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(x)?x:null;
