  const row=target.closest?.('.trab-table tbody tr'),cell=target.closest?.('td');
  if(row){const id=uuid((row.getAttribute('onclick')||'').match(/openDetail\('([^']+)'\)/)?.[1]);return{campo:columns[cell?.cellIndex]||'NINGUNO',trabajador_id:id};}
