  if(s.admin){s.channel=c.sb.channel('platinum-admin-actividad-'+s.sid).on('postgres_changes',{event:'*',schema:'public',table:'control_actividad_actual'},()=>refreshList(s)).subscribe(status=>{if(live!==s)return;s.connected=status==='SUBSCRIBED';if(s.open){render(s);refreshList(s);}});}
