 async function stop(){serial++;const s=live;live=null;const panel=doc().getElementById('act-live-panel'),body=doc().getElementById('act-live-body'),btn=doc().getElementById('act-live-open');if(panel)panel.hidden=true;if(body)body.innerHTML='';if(btn)btn.hidden=true;if(!s)return;s.cleanups.forEach(f=>f());cfg.window.clearInterval(s.heartbeat);if(s.listTimer)cfg.window.clearTimeout(s.listTimer);clearMarker();await s.reporter?.stop();if(s.channel)await cfg.context().sb.removeChannel(s.channel).catch(()=>{});await rpc('SALIR',{sesion_id:s.sid}).catch(()=>{});}
