    premioCapturado,premiosPag,premioAnulado:faltas>0&&premioCapturado>0,obrDia:Math.round(obrDia*10000)/10000,imssObr,isrBruto:ordinario.isrBruto,subsidio:ordinario.subsidio,isr,neto:r(bruto-imssObr-isr),
